-- Import September 18, 2026 reports. New customer IDs only; existing accounts are untouched.
-- Safe to rerun. No passwords, notifications or installer accounts are created.
-- INC Start Date is NOT assumed to be the INC status-entry date.
BEGIN;
LOCK TABLE production.jobs IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE sept18_import(data jsonb) ON COMMIT DROP;
CREATE TEMP TABLE sept18_results(number text, result text) ON COMMIT DROP;
DO $import$
DECLARE r record; j jsonb; sid text; iid text; label text; n integer;
BEGIN
 FOR r IN SELECT data FROM sept18_import LOOP
  j:=r.data->'job';
  IF EXISTS(SELECT 1 FROM production.jobs WHERE payload::jsonb->>'number'=j->>'number') THEN
  END IF;
  sid:=NULL; iid:=NULL;
  label:=CASE j#>>'{importSource,fsCode}' WHEN 'CR' THEN 'Cory Russell' WHEN 'KP' THEN 'Keith Pilcher' ELSE NULL END;
  SELECT count(*),min(id) INTO n,sid FROM production.members WHERE active=1 AND role IN ('admin','supervisor') AND lower(name)=lower(label);
  IF n<>1 THEN sid:=NULL; END IF;
  SELECT count(*),min(id) INTO n,iid FROM production.members WHERE role='installer' AND installer_code=j#>>'{importSource,crewCode}' AND installer_code<>'';
  IF n<>1 THEN iid:=NULL; END IF;
  j:=j || jsonb_build_object('supervisorId',sid,'supervisor',coalesce((SELECT name FROM production.members WHERE id=sid),'Unassigned'),'installerId',iid,'crew',coalesce((SELECT name FROM production.members WHERE id=iid),nullif(j#>>'{importSource,crewCode}',''),'Unassigned'));
 END LOOP;
END $import$;
SELECT result,count(*) AS accounts FROM sept18_results GROUP BY result;
COMMIT;
